-- Mirrors the production jobforger-db schema (migrations 0000-0003 of the original app).
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, password_salt text NOT NULL, name text NOT NULL, created_at integer);
CREATE TABLE IF NOT EXISTS profiles (id text PRIMARY KEY NOT NULL, user_id text NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, linkedin_url text, summary text, phone text, location text, website text, github text, image_url text, languages text);
CREATE TABLE IF NOT EXISTS experiences (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, company text NOT NULL, role text NOT NULL, location text, start_date text NOT NULL, end_date text, description text, bullets text, "order" integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS education (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, institution text NOT NULL, degree text NOT NULL, field text, start_date text NOT NULL, end_date text, gpa text, description text, "order" integer DEFAULT 0, coursework text);
CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, description text, tech_stack text, url text, repo_url text, start_date text, end_date text, "order" integer DEFAULT 0);
CREATE TABLE IF NOT EXISTS skills (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, category text, proficiency integer, source text DEFAULT 'manual');
CREATE TABLE IF NOT EXISTS cvs (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, latex_content text NOT NULL, created_at integer, updated_at integer);
CREATE TABLE IF NOT EXISTS cover_letters (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, latex_content text NOT NULL, created_at integer, updated_at integer);
CREATE TABLE IF NOT EXISTS applications (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, company text NOT NULL, position text NOT NULL, job_url text, job_description text, status text DEFAULT 'wishlist', cv_id text REFERENCES cvs(id), cover_letter_id text REFERENCES cover_letters(id), applied_at integer, notes text, created_at integer);
CREATE TABLE IF NOT EXISTS application_questions (id text PRIMARY KEY NOT NULL, application_id text NOT NULL REFERENCES applications(id) ON DELETE CASCADE, question text NOT NULL, answer text, ai_generated integer DEFAULT 0, created_at integer);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, token text NOT NULL UNIQUE, expires_at integer NOT NULL, used_at integer, created_at integer);
